'use strict';
/**
 * Writes supabase/schema.sql from the SCHEMA constant in server/db.js, so the
 * SQL file you paste into Supabase can never drift from what the server expects.
 * Run: npm run schema
 */
const fs = require('fs');
const path = require('path');
const { SCHEMA, TABLES } = require('../server/db');

const rls = TABLES.map((t) => 'ALTER TABLE public.' + t + ' ENABLE ROW LEVEL SECURITY;').join('\n');

const out = `-- RCMP database schema for PostgreSQL 16 / Supabase.
-- GENERATED by "npm run schema" from server/db.js. Do not edit by hand.
--
-- How to use: Supabase dashboard > SQL Editor > New query > paste this file > Run.
-- It is safe to run more than once (every statement is IF NOT EXISTS / idempotent).
-- The server also creates these tables itself on start-up, so this file is optional,
-- but running it first lets you check the database before deploying.

${SCHEMA.trim()}

-- ---------------------------------------------------------------------------
-- Security for Supabase. Supabase exposes every table in the "public" schema
-- through its REST API using the public "anon" key. RCMP never uses that API:
-- the Node server connects directly as the database owner (which bypasses
-- row level security). Enabling RLS with no policies, and revoking the API
-- roles, means nobody holding the anon key can read or change any row.
-- ---------------------------------------------------------------------------
${rls}
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
${TABLES.map((t) => '    REVOKE ALL ON public.' + t + ' FROM anon, authenticated;').join('\n')}
  END IF;
END $$;
`;
fs.writeFileSync(path.join(__dirname, '..', 'supabase', 'schema.sql'), out);
console.log('Wrote supabase/schema.sql (' + TABLES.length + ' tables)');
